export type OrderState = "placed" | "paid" | "packed" | "shipped" | "delivered" | "cancelled";

const nextStates: Readonly<Record<Exclude<OrderState, "cancelled">, OrderState | undefined>> = {
  placed: "paid",
  paid: "packed",
  packed: "shipped",
  shipped: "delivered",
  delivered: undefined,
};

export class OrderLine {
  public constructor(
    public readonly productId: string,
    public readonly quantity: number,
  ) {
    if (!productId.trim()) throw new Error("Product id is required");
    if (!Number.isInteger(quantity) || quantity <= 0) throw new Error("Quantity must be a positive integer");
  }
}

export class Order {
  private currentState: OrderState;

  public constructor(
    public readonly id: string,
    public readonly lines: readonly OrderLine[],
    state: OrderState = "placed",
  ) {
    if (!id.trim()) throw new Error("Order id is required");
    if (lines.length === 0) throw new Error("An order needs at least one line");
    this.currentState = state;
  }

  public get state(): OrderState {
    return this.currentState;
  }

  public advanceTo(state: OrderState): void {
    if (state === "cancelled" || this.currentState === "cancelled") {
      throw new Error("Cancelled orders cannot change state");
    }
    if (nextStates[this.currentState] !== state) {
      throw new Error(`Order can only move from ${this.currentState} to ${nextStates[this.currentState] ?? "no further state"}`);
    }
    this.currentState = state;
  }

  public cancel(): void {
    if (this.currentState === "shipped" || this.currentState === "delivered" || this.currentState === "cancelled") {
      throw new Error("Only orders before shipment can be cancelled");
    }
    this.currentState = "cancelled";
  }
}

